//! Persistent grid orchestration. Configuration is generated by `grid.rs`
//! from its attributed Tranquillity sources. No HTTP capture proxy is needed
//! for a manual viewer session: every advertised address is a real listener.

use std::net::Ipv4Addr;

pub(super) fn up(bind: Ipv4Addr) -> Result<String, String> {
    validate_bind(bind)?;
    #[cfg(target_os = "linux")]
    {
        up_linux(bind)
    }
    #[cfg(not(target_os = "linux"))]
    {
        Err("cargo xtask live runs on Linux".to_string())
    }
}

fn validate_bind(bind: Ipv4Addr) -> Result<(), String> {
    if bind.is_unspecified() || bind.is_multicast() || bind.is_broadcast() {
        return Err("grid --bind needs a concrete unicast IPv4 address to advertise".to_owned());
    }
    Ok(())
}

#[cfg(target_os = "linux")]
fn up_linux(bind: Ipv4Addr) -> Result<String, String> {
    use super::*;
    use std::os::unix::fs::{OpenOptionsExt, PermissionsExt};

    if !bind.is_loopback() {
        eprintln!(
            "WARNING: --bind {bind} exposes this test grid and its private Robust services beyond loopback; use only on a trusted test network."
        );
    }
    if let Some(pid) = live::standalone_is_up()? {
        return Err(format!(
            "the harness is already up (pid {pid}); cargo xtask live down stops it"
        ));
    }
    let state = crate::grid_state::claim()?;
    live::ensure_region_built()?;
    let ports = crate::ports::alloc_slots(&[
        crate::ports::Slot::RobustPublic,
        crate::ports::Slot::RobustPrivate,
        crate::ports::Slot::Home,
        crate::ports::Slot::Neighbour,
    ])?;
    let [public_port, private_port, home_port, neighbour_port]: [u16; 4] = ports
        .try_into()
        .map_err(|_| "could not allocate four local grid ports")?;
    let root = grid_root();
    if root.exists() {
        fs::remove_dir_all(&root)
            .map_err(|error| format!("could not clear {}: {error}", root.display()))?;
    }
    fs::create_dir_all(&root)
        .map_err(|error| format!("could not create {}: {error}", root.display()))?;
    fs::set_permissions(&root, fs::Permissions::from_mode(0o700))
        .map_err(|error| format!("could not protect grid directory: {error}"))?;
    crate::ports::write_fixture_ports(&root)?;
    let password = live::generate_password()?;
    let chat = live::generate_password()?;
    let password_file = root.join("password");
    live::write_secret(&password_file, &password)?;
    let commit = Command::new("git")
        .args(["rev-parse", "HEAD"])
        .current_dir(crate::repo_root())
        .output()
        .map_err(|error| format!("could not read Ferroan commit: {error}"))?;
    let commit_text =
        String::from_utf8(commit.stdout).map_err(|_| "Ferroan commit is not UTF-8")?;
    let commit_text = commit_text.trim();
    if !commit.status.success()
        || commit_text.len() != 40
        || !commit_text.bytes().all(|b| b.is_ascii_hexdigit())
    {
        return Err("could not read the Ferroan commit".to_owned());
    }
    let mut grid = Grid {
        robust: None,
        home: None,
        neighbour: None,
        rust_assets: None,
        proxies: None,
        passwords: vec![password.clone(), chat.clone()],
        _state: state,
    };

    // At the pin, CommandConsole.ReadLine reads stdin and
    // GridConsoleRunnerService repeatedly calls Prompt even after EOF. A FIFO
    // opened read/write becomes the child's stdin, so that fd itself keeps a
    // writer alive after this controller exits. It remains blocked awaiting a
    // command instead of spinning. The fresh private directory excludes stale
    // files/symlinks; no console credentials go on the command line.
    let console_path = root.join("robust-console");
    let status = Command::new("mkfifo")
        .arg("--mode=600")
        .arg(&console_path)
        .status()
        .map_err(|error| format!("could not create grid console FIFO: {error}"))?;
    if !status.success() {
        return Err("could not create grid console FIFO".to_owned());
    }
    let console = fs::OpenOptions::new()
        .read(true)
        .write(true)
        .mode(0o600)
        .open(&console_path)
        .map_err(|error| format!("could not open grid console FIFO: {error}"))?;
    grid.robust = Some(start_robust_at(
        &root,
        public_port,
        private_port,
        &grid.passwords,
        bind,
        Some(&console),
        ServiceUris {
            asset: None,
            account: None,
            auth: None,
        },
        false,
    )?);
    for (first, last, secret, email, id) in [
        (
            "Test",
            "User",
            password.as_str(),
            "test@example.invalid",
            live::ESTATE_OWNER,
        ),
        (
            "Chat",
            "Bot",
            chat.as_str(),
            "chat@example.invalid",
            live::CHAT_USER,
        ),
    ] {
        create_account(
            require_started_mut(&mut grid.robust, "Robust")?,
            first,
            last,
            secret,
            email,
            id,
            &grid.passwords,
        )?;
    }
    let publish = live::publish_dir();
    live::copy_example(&publish, "GridCommon.ini")?;
    let source = live::source_dir();
    for (ferroan, name, uuid, x, y, port, directory) in [
        (
            true,
            HOME_NAME,
            live::REGION_UUID,
            HOME_X,
            HOME_Y,
            home_port,
            "home",
        ),
        (
            false,
            NEIGHBOUR_NAME,
            NEIGHBOUR_UUID,
            NEIGHBOUR_X,
            NEIGHBOUR_Y,
            neighbour_port,
            "neighbour",
        ),
    ] {
        let process = start_region(
            &root.join(directory),
            &publish,
            &source,
            &password,
            &RegionStart {
                ferroan,
                login_only: true,
                name,
                uuid,
                x,
                y,
                http_bind: bind,
                udp_bind: bind,
                advertised: bind,
                http_port: port,
                public_proxy: public_port,
                private_proxy: private_port,
                capture: None,
                asset_uri: None,
                account_uri: None,
                auth_uri: None,
                metrics_port: None,
                store: super::RegionStore::Standard,
                parcel_seed: None,
                basic_physics: false,
            },
            &grid.passwords,
            false,
        )?;
        if ferroan {
            grid.home = Some(process);
        } else {
            grid.neighbour = Some(process);
        }
    }
    let robust_pid = require_started(&grid.robust, "Robust")?.child.id();
    let home_pid = require_started(&grid.home, "home region")?.child.id();
    let neighbour_pid = require_started(&grid.neighbour, "neighbour")?.child.id();
    let report = format!(
        "mode: grid\nregion: ferroan\nlogin_uri: http://{bind}:{public_port}/\naccount: Test User\npassword_file: {}\nrobust_private_uri: http://{bind}:{private_port}/\nrobust_pid: {robust_pid}\nhome_pid: {home_pid}\nneighbour_pid: {neighbour_pid}\nrobust_public_http: {bind}:{public_port}\nrobust_private_http: {bind}:{private_port}\nhome_http: {bind}:{home_port}\nhome_udp: {bind}:{home_port}\nneighbour_http: {bind}:{neighbour_port}\nneighbour_udp: {bind}:{neighbour_port}\nferroan_commit: {commit_text}\nstop: cargo xtask live down",
        password_file.display()
    );
    // Only detach after every process is ready and the full report exists.
    // Dropping Child releases the parent's handle, not the process. Their
    // identity records remain for live down, including interrupted up runs.
    for slot in [&mut grid.home, &mut grid.neighbour, &mut grid.robust] {
        if let Some(process) = slot.as_mut() {
            process.detached = true;
        }
    }
    Ok(report)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn advertised_bind_requires_one_concrete_unicast_address() {
        assert!(validate_bind(Ipv4Addr::LOCALHOST).is_ok());
        assert!(validate_bind(Ipv4Addr::new(192, 0, 2, 7)).is_ok());
        for bind in [
            Ipv4Addr::UNSPECIFIED,
            Ipv4Addr::BROADCAST,
            Ipv4Addr::new(224, 0, 0, 1),
        ] {
            assert!(validate_bind(bind).is_err());
        }
    }
}
